# Check 3-colorability via brute force
import itertools

def is_proper_coloring(col):
    for u,v in edges:
        if col[u] == col[v]:
            return False
    return True

found = False
for cols in itertools.product(range(3), repeat=n):
    if is_proper_coloring(cols):
        found = True
        print("3-coloring found:", cols)
        break

print("3-colorable:", found)

# Check chi >= 3 by checking if 2-colorable (bipartite)
from collections import deque

def is_bipartite():
    color = [-1]*n
    for start in range(n):
        if color[start] == -1:
            queue = deque([start])
            color[start] = 0
            while queue:
                u = queue.popleft()
                for v in range(n):
                    # check if edge exists
                    if (u,v) in edges or (v,u) in edges:
                        if color[v] == -1:
                            color[v] = 1-color[u]
                            queue.append(v)
                        elif color[v] == color[u]:
                            return False
    return True

print("Bipartite (2-colorable):", is_bipartite())
